// generated by tools/build_verse_manifests.js from dc_english.js — Dual-view English for the chapters of dc_verses/dc41_50.js
registerEnglish([["D&C",41,1,"Hearken and hear, O ye my people, saith the Lord and your God, ye whom I delight to bless with the greatest of all blessings, ye that hear me; and ye that hear me not will I curse, that have professed my name, with the heaviest of all cursings."],["D&C",41,2,"Hearken, O ye elders of my church whom I have called, behold I give unto you a commandment, that ye shall assemble yourselves together to agree upon my word;"],["D&C",41,3,"And by the prayer of your faith ye shall receive my law, that ye may know how to govern my church and have all things right before me."],["D&C",41,4,"And I will be your ruler when I come; and behold, I come quickly, and ye shall see that my law is kept."],["D&C",41,5,"He that receiveth my law and doeth it, the same is my disciple; and he that saith he receiveth it and doeth it not, the same is not my disciple, and shall be cast out from among you;"],["D&C",41,6,"For it is not meet that the things which belong to the children of the kingdom should be given to them that are not worthy, or to dogs, or the pearls to be cast before swine."],["D&C",41,7,"And again, it is meet that my servant Joseph Smith, Jun., should have a house built, in which to live and translate."],["D&C",41,8,"And again, it is meet that my servant Sidney Rigdon should live as seemeth him good, inasmuch as he keepeth my commandments."],["D&C",41,9,"And again, I have called my servant Edward Partridge; and I give a commandment, that he should be appointed by the voice of the church, and ordained a bishop unto the church, to leave his merchandise and to spend all his time in the labors of the church;"],["D&C",41,10,"To see to all things as it shall be appointed unto him in my laws in the day that I shall give them."],["D&C",41,11,"And this because his heart is pure before me, for he is like unto Nathanael of old, in whom there is no guile."],["D&C",41,12,"These words are given unto you, and they are pure before me; wherefore, beware how you hold them, for they are to be answered upon your souls in the day of judgment. Even so. Amen."],["D&C",42,1,"Hearken, O ye elders of my church, who have assembled yourselves together in my name, even Jesus Christ the Son of the living God, the Savior of the world; inasmuch as ye believe on my name and keep my commandments."],["D&C",42,2,"Again I say unto you, hearken and hear and obey the law which I shall give unto you."],["D&C",42,3,"For verily I say, as ye have assembled yourselves together according to the commandment wherewith I commanded you, and are agreed as touching this one thing, and have asked the Father in my name, even so ye shall receive."],["D&C",42,4,"Behold, verily I say unto you, I give unto you this first commandment, that ye shall go forth in my name, every one of you, excepting my servants Joseph Smith, Jun., and Sidney Rigdon."],["D&C",42,5,"And I give unto them a commandment that they shall go forth for a little season, and it shall be given by the power of the Spirit when they shall return."],["D&C",42,6,"And ye shall go forth in the power of my Spirit, preaching my gospel, two by two, in my name, lifting up your voices as with the sound of a trump, declaring my word like unto angels of God."],["D&C",42,7,"And ye shall go forth baptizing with water, saying: Repent ye, repent ye, for the kingdom of heaven is at hand."],["D&C",42,8,"And from this place ye shall go forth into the regions westward; and inasmuch as ye shall find them that will receive you ye shall build up my church in every region—"],["D&C",42,9,"Until the time shall come when it shall be revealed unto you from on high, when the city of the New Jerusalem shall be prepared, that ye may be gathered in one, that ye may be my people and I will be your God."],["D&C",42,10,"And again, I say unto you, that my servant Edward Partridge shall stand in the office whereunto I have appointed him. And it shall come to pass, that if he transgress another shall be appointed in his stead. Even so. Amen."],["D&C",42,11,"Again I say unto you, that it shall not be given to any one to go forth to preach my gospel, or to build up my church, except he be ordained by some one who has authority, and it is known to the church that he has authority and has been regularly ordained by the heads of the church."],["D&C",42,12,"And again, the elders, priests and teachers of this church shall teach the principles of my gospel, which are in the Bible and the Book of Mormon, in the which is the fulness of the gospel."],["D&C",42,13,"And they shall observe the covenants and church articles to do them, and these shall be their teachings, as they shall be directed by the Spirit."],["D&C",42,14,"And the Spirit shall be given unto you by the prayer of faith; and if ye receive not the Spirit ye shall not teach."],["D&C",42,15,"And all this ye shall observe to do as I have commanded concerning your teaching, until the fulness of my scriptures is given."],["D&C",42,16,"And as ye shall lift up your voices by the Comforter, ye shall speak and prophesy as seemeth me good;"],["D&C",42,17,"For, behold, the Comforter knoweth all things, and beareth record of the Father and of the Son."],["D&C",42,18,"And now, behold, I speak unto the church. Thou shalt not kill; and he that kills shall not have forgiveness in this world, nor in the world to come."],["D&C",42,19,"And again, I say, thou shalt not kill; but he that killeth shall die."],["D&C",42,20,"Thou shalt not steal; and he that stealeth and will not repent shall be cast out."],["D&C",42,21,"Thou shalt not lie; he that lieth and will not repent shall be cast out."],["D&C",42,22,"Thou shalt love thy wife with all thy heart, and shalt cleave unto her and none else."],["D&C",42,23,"And he that looketh upon a woman to lust after her shall deny the faith, and shall not have the Spirit; and if he repents not he shall be cast out."],["D&C",42,24,"Thou shalt not commit adultery; and he that committeth adultery, and repenteth not, shall be cast out."],["D&C",42,25,"But he that has committed adultery and repents with all his heart, and forsaketh it, and doeth it no more, thou shalt forgive;"],["D&C",42,26,"But if he doeth it again, he shall not be forgiven, but shall be cast out."],["D&C",42,27,"Thou shalt not speak evil of thy neighbor, nor do him any harm."],["D&C",42,28,"Thou knowest my laws concerning these things are given in my scriptures; he that sinneth and repenteth not shall be cast out."],["D&C",42,29,"If thou lovest me thou shalt serve me and keep all my commandments."],["D&C",42,30,"And behold, thou wilt remember the poor, and consecrate of thy properties for their support that which thou hast to impart unto them, with a covenant and a deed which cannot be broken."],["D&C",42,31,"And inasmuch as ye impart of your substance unto the poor, ye will do it unto me; and they shall be laid before the bishop of my church and his counselors, two of the elders, or high priests, such as he shall appoint or has appointed and set apart for that purpose."],["D&C",42,32,"And it shall come to pass, that after they are laid before the bishop of my church, and after that he has received these testimonies concerning the consecration of the properties of my church, that they cannot be taken from the church, agreeable to my commandments, every man shall be made accountable unto me, a steward over his own property, or that which he has received by consecration, as much as is sufficient for himself and family."],["D&C",42,33,"And again, if there shall be properties in the hands of the church, or any individuals of it, more than is necessary for their support after this first consecration, which is a residue to be consecrated unto the bishop, it shall be kept to administer to those who have not, from time to time, that every man who has need may be amply supplied and receive according to his wants."],["D&C",42,34,"Therefore, the residue shall be kept in my storehouse, to administer to the poor and the needy, as shall be appointed by the high council of the church, and the bishop and his council;"],["D&C",42,35,"And for the purpose of purchasing lands for the public benefit of the church, and building houses of worship, and building up of the New Jerusalem which is hereafter to be revealed—"],["D&C",42,36,"That my covenant people may be gathered in one in that day when I shall come to my temple. And this I do for the salvation of my people."],["D&C",42,37,"And it shall come to pass, that he that sinneth and repenteth not shall be cast out of the church, and shall not receive again that which he has consecrated unto the poor and the needy of my church, or in other words, unto me—"],["D&C",42,38,"For inasmuch as ye do it unto the least of these, ye do it unto me."],["D&C",42,39,"For it shall come to pass, that which I spake by the mouths of my prophets shall be fulfilled; for I will consecrate of the riches of those who embrace my gospel among the Gentiles unto the poor of my people who are of the house of Israel."],["D&C",42,40,"And again, thou shalt not be proud in thy heart; let all thy garments be plain, and their beauty the beauty of the work of thine own hands;"],["D&C",42,41,"And let all things be done in cleanliness before me."],["D&C",42,42,"Thou shalt not be idle; for he that is idle shall not eat the bread nor wear the garments of the laborer."],["D&C",42,43,"And whosoever among you are sick, and have not faith to be healed, but believe, shall be nourished with all tenderness, with herbs and mild food, and that not by the hand of an enemy."],["D&C",42,44,"And the elders of the church, two or more, shall be called, and shall pray for and lay their hands upon them in my name; and if they die they shall die unto me, and if they live they shall live unto me."],["D&C",42,45,"Thou shalt live together in love, insomuch that thou shalt weep for the loss of them that die, and more especially for those that have not hope of a glorious resurrection."],["D&C",42,46,"And it shall come to pass that those that die in me shall not taste of death, for it shall be sweet unto them;"],["D&C",42,47,"And they that die not in me, wo unto them, for their death is bitter."],["D&C",42,48,"And again, it shall come to pass that he that hath faith in me to be healed, and is not appointed unto death, shall be healed."],["D&C",42,49,"He who hath faith to see shall see."],["D&C",42,50,"He who hath faith to hear shall hear."],["D&C",42,51,"The lame who hath faith to leap shall leap."],["D&C",42,52,"And they who have not faith to do these things, but believe in me, have power to become my sons; and inasmuch as they break not my laws thou shalt bear their infirmities."],["D&C",42,53,"Thou shalt stand in the place of thy stewardship."],["D&C",42,54,"Thou shalt not take thy brother's garment; thou shalt pay for that which thou shalt receive of thy brother."],["D&C",42,55,"And if thou obtainest more than that which would be for thy support, thou shalt give it into my storehouse, that all things may be done according to that which I have said."],["D&C",42,56,"Thou shalt ask, and my scriptures shall be given as I have appointed, and they shall be preserved in safety;"],["D&C",42,57,"And it is expedient that thou shouldst hold thy peace concerning them, and not teach them until ye have received them in full."],["D&C",42,58,"And I give unto you a commandment that then ye shall teach them unto all men; for they shall be taught unto all nations, kindreds, tongues and people."],["D&C",42,59,"Thou shalt take the things which thou hast received, which have been given unto thee in my scriptures for a law, to be my law to govern my church;"],["D&C",42,60,"And he that doeth according to these things shall be saved, and he that doeth them not shall be damned if he so continue."],["D&C",42,61,"If thou shalt ask, thou shalt receive revelation upon revelation, knowledge upon knowledge, that thou mayest know the mysteries and peaceable things—that which bringeth joy, that which bringeth life eternal."],["D&C",42,62,"Thou shalt ask, and it shall be revealed unto you in mine own due time where the New Jerusalem shall be built."],["D&C",42,63,"And behold, it shall come to pass that my servants shall be sent forth to the east and to the west, to the north and to the south."],["D&C",42,64,"And even now, let him that goeth to the east teach them that shall be converted to flee to the west, and this in consequence of that which is coming on the earth, and of secret combinations."],["D&C",42,65,"Behold, thou shalt observe all these things, and great shall be thy reward; for unto you it is given to know the mysteries of the kingdom, but unto the world it is not given to know them."],["D&C",42,66,"Ye shall observe the laws which ye have received and be faithful."],["D&C",42,67,"And ye shall hereafter receive church covenants, such as shall be sufficient to establish you, both here and in the New Jerusalem."],["D&C",42,68,"Therefore, he that lacketh wisdom, let him ask of me, and I will give him liberally and upbraid him not."],["D&C",42,69,"Lift up your hearts and rejoice, for unto you the kingdom, or in other words, the keys of the church have been given. Even so. Amen."],["D&C",42,70,"The priests and teachers shall have their stewardships, even as the members."],["D&C",42,71,"And the elders or high priests who are appointed to assist the bishop as counselors in all things, are to have their families supported out of the property which is consecrated to the bishop, for the good of the poor, and for other purposes, as before mentioned;"],["D&C",42,72,"Or they are to receive a just remuneration for all their services, either a stewardship or otherwise, as may be thought best or decided by the counselors and bishop."],["D&C",42,73,"And the bishop, also, shall receive his support, or a just remuneration for all his services in the church."],["D&C",42,74,"Behold, verily I say unto you, that whatever persons among you, having put away their companions for the cause of fornication, or in other words, if they shall testify before you in all lowliness of heart that this is the case, ye shall not cast them out from among you;"],["D&C",42,75,"But if ye shall find that any persons have left their companions for the sake of adultery, and they themselves are the offenders, and their companions are living, they shall be cast out from among you."],["D&C",42,76,"And again, I say unto you, that ye shall be watchful and careful, with all inquiry, that ye receive none such among you if they are married;"],["D&C",42,77,"And if they are not married, they shall repent of all their sins or ye shall not receive them."],["D&C",42,78,"And again, every person who belongeth to this church of Christ, shall observe to keep all the commandments and covenants of the church."],["D&C",42,79,"And it shall come to pass, that if any persons among you shall kill they shall be delivered up and dealt with according to the laws of the land; for remember that he hath no forgiveness; and it shall be proved according to the laws of the land."],["D&C",42,80,"And if any man or woman shall commit adultery, he or she shall be tried before two elders of the church, or more, and every word shall be established against him or her by two witnesses of the church, and not of the enemy; but if there are more than two witnesses it is better."],["D&C",42,81,"But he or she shall be condemned by the mouth of two witnesses; and the elders shall lay the case before the church, and the church shall lift up their hands against him or her, that they may be dealt with according to the law of God."],["D&C",42,82,"And if it can be, it is necessary that the bishop be present also."],["D&C",42,83,"And thus ye shall do in all cases which shall come before you."],["D&C",42,84,"And if a man or woman shall rob, he or she shall be delivered up unto the law of the land."],["D&C",42,85,"And if he or she shall steal, he or she shall be delivered up unto the law of the land."],["D&C",42,86,"And if he or she shall lie, he or she shall be delivered up unto the law of the land."],["D&C",42,87,"And if he or she do any manner of iniquity, he or she shall be delivered up unto the law, even that of God."],["D&C",42,88,"And if thy brother or sister offend thee, thou shalt take him or her between him or her and thee alone; and if he or she confess thou shalt be reconciled."],["D&C",42,89,"And if he or she confess not thou shalt deliver him or her up unto the church, not to the members, but to the elders. And it shall be done in a meeting, and that not before the world."],["D&C",42,90,"And if thy brother or sister offend many, he or she shall be chastened before many."],["D&C",42,91,"And if any one offend openly, he or she shall be rebuked openly, that he or she may be ashamed. And if he or she confess not, he or she shall be delivered up unto the law of God."],["D&C",42,92,"If any shall offend in secret, he or she shall be rebuked in secret, that he or she may have opportunity to confess in secret to him or her whom he or she has offended, and to God, that the church may not speak reproachfully of him or her."],["D&C",42,93,"And thus shall ye conduct in all things."],["D&C",43,1,"O hearken, ye elders of my church, and give ear to the words which I shall speak unto you."],["D&C",43,2,"For behold, verily, verily, I say unto you, that ye have received a commandment for a law unto my church, through him whom I have appointed unto you to receive commandments and revelations from my hand."],["D&C",43,3,"And this ye shall know assuredly—that there is none other appointed unto you to receive commandments and revelations until he be taken, if he abide in me."],["D&C",43,4,"But verily, verily, I say unto you, that none else shall be appointed unto this gift except it be through him; for if it be taken from him he shall not have power except to appoint another in his stead."],["D&C",43,5,"And this shall be a law unto you, that ye receive not the teachings of any that shall come before you as revelations or commandments;"],["D&C",43,6,"And this I give unto you that you may not be deceived, that you may know they are not of me."],["D&C",43,7,"For verily I say unto you, that he that is ordained of me shall come in at the gate and be ordained as I have told you before, to teach those revelations which you have received and shall receive through him whom I have appointed."],["D&C",43,8,"And now, behold, I give unto you a commandment, that when ye are assembled together ye shall instruct and edify each other, that ye may know how to act and direct my church, how to act upon the points of my law and commandments, which I have given."],["D&C",43,9,"And thus ye shall become instructed in the law of my church, and be sanctified by that which ye have received, and ye shall bind yourselves to act in all holiness before me—"],["D&C",43,10,"That inasmuch as ye do this, glory shall be added to the kingdom which ye have received. Inasmuch as ye do it not, it shall be taken, even that which ye have received."],["D&C",43,11,"Purge ye out the iniquity which is among you; sanctify yourselves before me;"],["D&C",43,12,"And if ye desire the glories of the kingdom, appoint ye my servant Joseph Smith, Jun., and uphold him before me by the prayer of faith."],["D&C",43,13,"And again, I say unto you, that if ye desire the mysteries of the kingdom, provide for him food and raiment, and whatsoever thing he needeth to accomplish the work wherewith I have commanded him;"],["D&C",43,14,"And if ye do it not he shall remain unto them that have received him, that I may reserve unto myself a pure people before me."],["D&C",43,15,"Again I say, hearken ye elders of my church, whom I have appointed: Ye are not sent forth to be taught, but to teach the children of men the things which I have put into your hands by the power of my Spirit;"],["D&C",43,16,"And ye are to be taught from on high. Sanctify yourselves and ye shall be endowed with power, that ye may give even as I have spoken."],["D&C",43,17,"Hearken ye, for, behold, the great day of the Lord is nigh at hand."],["D&C",43,18,"For the day cometh that the Lord shall utter his voice out of heaven; the heavens shall shake and the earth shall tremble, and the trump of God shall sound both long and loud, and shall say to the sleeping nations: Ye saints arise and live; ye sinners stay and sleep until I shall call again."],["D&C",43,19,"Wherefore gird up your loins lest ye be found among the wicked."],["D&C",43,20,"Lift up your voices and spare not. Call upon the nations to repent, both old and young, both bond and free, saying: Prepare yourselves for the great day of the Lord;"],["D&C",43,21,"For if I, who am a man, do lift up my voice and call upon you to repent, and ye hate me, what will ye say when the day cometh when the thunders shall utter their voices from the ends of the earth, speaking to the ears of all that live, saying—Repent, and prepare for the great day of the Lord?"],["D&C",43,22,"Yea, and again, when the lightnings shall streak forth from the east unto the west, and shall utter forth their voices unto all that live, and make the ears of all tingle that hear, saying these words—Repent ye, for the great day of the Lord is come?"],["D&C",43,23,"And again, the Lord shall utter his voice out of heaven, saying: Hearken, O ye nations of the earth, and hear the words of that God who made you."],["D&C",43,24,"O, ye nations of the earth, how often would I have gathered you together as a hen gathereth her chickens under her wings, but ye would not!"],["D&C",43,25,"How oft have I called upon you by the mouth of my servants, and by the ministering of angels, and by mine own voice, and by the voice of thunderings, and by the voice of lightnings, and by the voice of tempests, and by the voice of earthquakes, and great hailstorms, and by the voice of famines and pestilences of every kind, and by the great sound of a trump, and by the voice of judgment, and by the voice of mercy all the day long, and by the voice of glory and honor and the riches of eternal life, and would have saved you with an everlasting salvation, but ye would not!"],["D&C",43,26,"Behold, the day has come, when the cup of the wrath of mine indignation is full."],["D&C",43,27,"Behold, verily I say unto you, that these are the words of the Lord your God."],["D&C",43,28,"Wherefore, labor ye, labor ye in my vineyard for the last time—for the last time call upon the inhabitants of the earth."],["D&C",43,29,"For in mine own due time will I come upon the earth in judgment, and my people shall be redeemed and shall reign with me on earth."],["D&C",43,30,"For the great Millennium, of which I have spoken by the mouth of my servants, shall come."],["D&C",43,31,"For Satan shall be bound, and when he is loosed again he shall only reign for a little season, and then cometh the end of the earth."],["D&C",43,32,"And he that liveth in righteousness shall be changed in the twinkling of an eye, and the earth shall pass away so as by fire."],["D&C",43,33,"And the wicked shall go away into unquenchable fire, and their end no man knoweth on earth, nor ever shall know, until they come before me in judgment."],["D&C",43,34,"Hearken ye to these words. Behold, I am Jesus Christ, the Savior of the world. Treasure these things up in your hearts, and let the solemnities of eternity rest upon your minds."],["D&C",43,35,"Be sober. Keep all my commandments. Even so. Amen."],["D&C",44,1,"Behold, thus saith the Lord unto you my servants, it is expedient in me that the elders of my church should be called together, from the east and from the west, and from the north and from the south, by letter or some other way."],["D&C",44,2,"And it shall come to pass, that inasmuch as they are faithful, and exercise faith in me, I will pour out my Spirit upon them in the day that they assemble themselves together."],["D&C",44,3,"And it shall come to pass that they shall go forth into the regions round about, and preach repentance unto the people."],["D&C",44,4,"And many shall be converted, insomuch that ye shall obtain power to organize yourselves according to the laws of man;"],["D&C",44,5,"That your enemies may not have power over you; that you may be preserved in all things; that you may be enabled to keep my laws; that every bond may be broken wherewith the enemy seeketh to destroy my people."],["D&C",44,6,"Behold, I say unto you, that ye must visit the poor and the needy and administer to their relief, that they may be kept until all things may be done according to my law which ye have received. Amen."],["D&C",45,1,"Hearken, O ye people of my church, to whom the kingdom has been given; hearken ye and give ear to him who laid the foundation of the earth, who made the heavens and all the hosts thereof, and by whom all things were made which live, and move, and have a being."],["D&C",45,2,"And again I say, hearken unto my voice, lest death shall overtake you; in an hour when ye think not the summer shall be past, and the harvest ended, and your souls not saved."],["D&C",45,3,"Listen to him who is the advocate with the Father, who is pleading your cause before him—"],["D&C",45,4,"Saying: Father, behold the sufferings and death of him who did no sin, in whom thou wast well pleased; behold the blood of thy Son which was shed, the blood of him whom thou gavest that thyself might be glorified;"],["D&C",45,5,"Wherefore, Father, spare these my brethren that believe on my name, that they may come unto me and have everlasting life."],["D&C",45,6,"Hearken, O ye people of my church, and ye elders listen together, and hear my voice while it is called today, and harden not your hearts;"],["D&C",45,7,"For verily I say unto you that I am Alpha and Omega, the beginning and the end, the light and the life of the world—a light that shineth in darkness and the darkness comprehendeth it not."],["D&C",45,8,"I came unto mine own, and mine own received me not; but unto as many as received me gave I power to do many miracles, and to become the sons of God; and even unto them that believed on my name gave I power to obtain eternal life."],["D&C",45,9,"And even so I have sent mine everlasting covenant into the world, to be a light to the world, and to be a standard for my people, and for the Gentiles to seek to it, and to be a messenger before my face to prepare the way before me."],["D&C",45,10,"Wherefore, come ye unto it, and with him that cometh I will reason as with men in days of old, and I will show unto you my strong reasoning."],["D&C",45,11,"Wherefore, hearken ye together and let me show unto you even my wisdom—the wisdom of him whom ye say is the God of Enoch, and his brethren,"],["D&C",45,12,"Who were separated from the earth, and were received unto myself—a city reserved until a day of righteousness shall come—a day which was sought for by all holy men, and they found it not because of wickedness and abominations;"],["D&C",45,13,"And confessed they were strangers and pilgrims on the earth;"],["D&C",45,14,"But obtained a promise that they should find it and see it in their flesh."],["D&C",45,15,"Wherefore, hearken and I will reason with you, and I will speak unto you and prophesy, as unto men in days of old."],["D&C",45,16,"And I will show it plainly as I showed it unto my disciples as I stood before them in the flesh, and spake unto them, saying: As ye have asked of me concerning the signs of my coming, in the day when I shall come in my glory in the clouds of heaven, to fulfil the promises that I have made unto your fathers,"],["D&C",45,17,"For as ye have looked upon the long absence of your spirits from your bodies to be a bondage, I will show unto you how the day of redemption shall come, and also the restoration of the scattered Israel."],["D&C",45,18,"And now ye behold this temple which is in Jerusalem, which ye call the house of God, and your enemies say that this house shall never fall."],["D&C",45,19,"But, verily I say unto you, that desolation shall come upon this generation as a thief in the night, and this people shall be destroyed and scattered among all nations."],["D&C",45,20,"And this temple which ye now see shall be thrown down that there shall not be left one stone upon another."],["D&C",45,21,"And it shall come to pass, that this generation of Jews shall not pass away until every desolation which I have told you concerning them shall come to pass."],["D&C",45,22,"Ye say that ye know that the end of the world cometh; ye say also that ye know that the heavens and the earth shall pass away;"],["D&C",45,23,"And in this ye say truly, for so it is; but these things which I have told you shall not pass away until all shall be fulfilled."],["D&C",45,24,"And this I have told you concerning Jerusalem; and when that day shall come, shall a remnant be scattered among all nations;"],["D&C",45,25,"But they shall be gathered again; but they shall remain until the times of the Gentiles be fulfilled."],["D&C",45,26,"And in that day shall be heard of wars and rumors of wars, and the whole earth shall be in commotion, and men's hearts shall fail them, and they shall say that Christ delayeth his coming until the end of the earth."],["D&C",45,27,"And the love of men shall wax cold, and iniquity shall abound."],["D&C",45,28,"And when the times of the Gentiles is come in, a light shall break forth among them that sit in darkness, and it shall be the fulness of my gospel;"],["D&C",45,29,"But they receive it not; for they perceive not the light, and they turn their hearts from me because of the precepts of men."],["D&C",45,30,"And in that generation shall the times of the Gentiles be fulfilled."],["D&C",45,31,"And there shall be men standing in that generation, that shall not pass until they shall see an overflowing scourge; for a desolating sickness shall cover the land."],["D&C",45,32,"But my disciples shall stand in holy places, and shall not be moved; but among the wicked, men shall lift up their voices and curse God and die."],["D&C",45,33,"And there shall be earthquakes also in divers places, and many desolations; yet men will harden their hearts against me, and they will take up the sword, one against another, and they will kill one another."],["D&C",45,34,"And now, when I the Lord had spoken these words unto my disciples, they were troubled."],["D&C",45,35,"And I said unto them: Be not troubled, for, when all these things shall come to pass, ye may know that the promises which have been made unto you shall be fulfilled."],["D&C",45,36,"And when the light shall begin to break forth, it shall be with them like unto a parable which I will show you—"],["D&C",45,37,"Ye look and behold the fig trees, and ye see them with your eyes, and ye say when they begin to shoot forth, and their leaves are yet tender, that summer is now nigh at hand;"],["D&C",45,38,"Even so it shall be in that day when they shall see all these things, then shall they know that the hour is nigh."],["D&C",45,39,"And it shall come to pass that he that feareth me shall be looking forth for the great day of the Lord to come, even for the signs of the coming of the Son of Man."],["D&C",45,40,"And they shall see signs and wonders, for they shall be shown forth in the heavens above, and in the earth beneath."],["D&C",45,41,"And they shall behold blood, and fire, and vapors of smoke."],["D&C",45,42,"And before the day of the Lord shall come, the sun shall be darkened, and the moon be turned into blood, and the stars fall from heaven."],["D&C",45,43,"And the remnant shall be gathered unto this place;"],["D&C",45,44,"And then they shall look for me, and, behold, I will come; and they shall see me in the clouds of heaven, clothed with power and great glory; with all the holy angels; and he that watches not for me shall be cut off."],["D&C",45,45,"But before the arm of the Lord shall fall, an angel shall sound his trump, and the saints that have slept shall come forth to meet me in the cloud."],["D&C",45,46,"Wherefore, if ye have slept in peace blessed are you; for as you now behold me and know that I am, even so shall ye come unto me and your souls shall live, and your redemption shall be perfected; and the saints shall come forth from the four quarters of the earth."],["D&C",45,47,"Then shall the arm of the Lord fall upon the nations."],["D&C",45,48,"And then shall the Lord set his foot upon this mount, and it shall cleave in twain, and the earth shall tremble, and reel to and fro, and the heavens also shall shake."],["D&C",45,49,"And the Lord shall utter his voice, and all the ends of the earth shall hear it; and the nations of the earth shall mourn, and they that have laughed shall see their folly."],["D&C",45,50,"And calamity shall cover the mocker, and the scorner shall be consumed; and they that have watched for iniquity shall be hewn down and cast into the fire."],["D&C",45,51,"And then shall the Jews look upon me and say: What are these wounds in thine hands and in thy feet?"],["D&C",45,52,"Then shall they know that I am the Lord; for I will say unto them: These wounds are the wounds with which I was wounded in the house of my friends. I am he who was lifted up. I am Jesus that was crucified. I am the Son of God."],["D&C",45,53,"And then shall they weep because of their iniquities; then shall they lament because they persecuted their king."],["D&C",45,54,"And then shall the heathen nations be redeemed, and they that knew no law shall have part in the first resurrection; and it shall be tolerable for them."],["D&C",45,55,"And Satan shall be bound, that he shall have no place in the hearts of the children of men."],["D&C",45,56,"And at that day, when I shall come in my glory, shall the parable be fulfilled which I spake concerning the ten virgins."],["D&C",45,57,"For they that are wise and have received the truth, and have taken the Holy Spirit for their guide, and have not been deceived—verily I say unto you, they shall not be hewn down and cast into the fire, but shall abide the day."],["D&C",45,58,"And the earth shall be given unto them for an inheritance; and they shall multiply and wax strong, and their children shall grow up without sin unto salvation."],["D&C",45,59,"For the Lord shall be in their midst, and his glory shall be upon them, and he will be their king and their lawgiver."],["D&C",45,60,"And now, behold, I say unto you, it shall not be given unto you to know any further concerning this chapter, until the New Testament be translated, and in it all these things shall be made known;"],["D&C",45,61,"Wherefore I give unto you that ye may now translate it, that ye may be prepared for the things to come."],["D&C",45,62,"For verily I say unto you, that great things await you;"],["D&C",45,63,"Ye hear of wars in foreign lands; but, behold, I say unto you, they are nigh, even at your doors, and not many years hence ye shall hear of wars in your own lands."],["D&C",45,64,"Wherefore I, the Lord, have said, gather ye out from the eastern lands, assemble ye yourselves together ye elders of my church; go ye forth into the western countries, call upon the inhabitants to repent, and inasmuch as they do repent, build up churches unto me."],["D&C",45,65,"And with one heart and with one mind, gather up your riches that ye may purchase an inheritance which shall hereafter be appointed unto you."],["D&C",45,66,"And it shall be called the New Jerusalem, a land of peace, a city of refuge, a place of safety for the saints of the Most High God;"],["D&C",45,67,"And the glory of the Lord shall be there, and the terror of the Lord also shall be there, insomuch that the wicked will not come unto it, and it shall be called Zion."],["D&C",45,68,"And it shall come to pass among the wicked, that every man that will not take his sword against his neighbor must needs flee unto Zion for safety."],["D&C",45,69,"And there shall be gathered unto it out of every nation under heaven; and it shall be the only people that shall not be at war one with another."],["D&C",45,70,"And it shall be said among the wicked: Let us not go up to battle against Zion, for the inhabitants of Zion are terrible; wherefore we cannot stand."],["D&C",45,71,"And it shall come to pass that the righteous shall be gathered out from among all nations, and shall come to Zion, singing with songs of everlasting joy."],["D&C",45,72,"And now I say unto you, keep these things from going abroad unto the world until it is expedient in me, that ye may accomplish this work in the eyes of the people, and in the eyes of your enemies, that they may not know your works until ye have accomplished the thing which I have commanded you;"],["D&C",45,73,"That when they shall know it, that they may consider these things."],["D&C",45,74,"For when the Lord shall appear he shall be terrible unto them, that fear may seize upon them, and they shall stand afar off and tremble."],["D&C",45,75,"And all nations shall be afraid because of the terror of the Lord, and the power of his might. Even so. Amen."],["D&C",46,1,"Hearken, O ye people of my church; for verily I say unto you that these things were spoken unto you for your profit and learning."],["D&C",46,2,"But notwithstanding those things which are written, it always has been given to the elders of my church from the beginning, and ever shall be, to conduct all meetings as they are directed and guided by the Holy Spirit."],["D&C",46,3,"Nevertheless ye are commanded never to cast any one out from your public meetings, which are held before the world."],["D&C",46,4,"Ye are also commanded not to cast any one who belongeth to the church out of your sacrament meetings; nevertheless, if any have trespassed, let him not partake until he makes reconciliation."],["D&C",46,5,"And again I say unto you, ye shall not cast any out of your sacrament meetings who are earnestly seeking the kingdom—I speak this concerning those who are not of the church."],["D&C",46,6,"And again I say unto you, concerning your confirmation meetings, that if there be any that are not of the church, that are earnestly seeking after the kingdom, ye shall not cast them out."],["D&C",46,7,"But ye are commanded in all things to ask of God, who giveth liberally; and that which the Spirit testifies unto you even so I would that ye should do in all holiness of heart, walking uprightly before me, considering the end of your salvation, doing all things with prayer and thanksgiving, that ye may not be seduced by evil spirits, or doctrines of devils, or the commandments of men; for some are of men, and others of devils."],["D&C",46,8,"Wherefore, beware lest ye are deceived; and that ye may not be deceived seek ye earnestly the best gifts, always remembering for what they are given;"],["D&C",46,9,"For verily I say unto you, they are given for the benefit of those who love me and keep all my commandments, and him that seeketh so to do; that all may be benefited that seek or that ask of me, that ask and not for a sign that they may consume it upon their lusts."],["D&C",46,10,"And again, verily I say unto you, I would that ye should always remember, and always retain in your minds what those gifts are, that are given unto the church."],["D&C",46,11,"For all have not every gift given unto them; for there are many gifts, and to every man is given a gift by the Spirit of God."],["D&C",46,12,"To some is given one, and to some is given another, that all may be profited thereby."],["D&C",46,13,"To some it is given by the Holy Ghost to know that Jesus Christ is the Son of God, and that he was crucified for the sins of the world."],["D&C",46,14,"To others it is given to believe on their words, that they also might have eternal life if they continue faithful."],["D&C",46,15,"And again, to some it is given by the Holy Ghost to know the differences of administration, as it will be pleasing unto the same Lord, according as the Lord will, suiting his mercies according to the conditions of the children of men."],["D&C",46,16,"And again, it is given by the Holy Ghost to some to know the diversities of operations, whether they be of God, that the manifestations of the Spirit may be given to every man to profit withal."],["D&C",46,17,"And again, verily I say unto you, to some is given, by the Spirit of God, the word of wisdom."],["D&C",46,18,"To another is given the word of knowledge, that all may be taught to be wise and to have knowledge."],["D&C",46,19,"And again, to some it is given to have faith to be healed;"],["D&C",46,20,"And to others it is given to have faith to heal."],["D&C",46,21,"And again, to some is given the working of miracles;"],["D&C",46,22,"And to others it is given to prophesy;"],["D&C",46,23,"And to others the discerning of spirits."],["D&C",46,24,"And again, it is given to some to speak with tongues;"],["D&C",46,25,"And to another is given the interpretation of tongues."],["D&C",46,26,"And all these gifts come from God, for the benefit of the children of God."],["D&C",46,27,"And unto the bishop of the church, and unto such as God shall appoint and ordain to watch over the church and to be elders unto the church, are to have it given unto them to discern all those gifts lest there shall be any among you professing and yet be not of God."],["D&C",46,28,"And it shall come to pass that he that asketh in Spirit shall receive in Spirit;"],["D&C",46,29,"That unto some it may be given to have all those gifts, that there may be a head, in order that every member may be profited thereby."],["D&C",46,30,"He that asketh in the Spirit asketh according to the will of God; wherefore it is done even as he asketh."],["D&C",46,31,"And again, I say unto you, all things must be done in the name of Christ, whatsoever you do in the Spirit;"],["D&C",46,32,"And ye must give thanks unto God in the Spirit for whatsoever blessing ye are blessed with."],["D&C",46,33,"And ye must practice virtue and holiness before me continually. Even so. Amen."],["D&C",47,1,"Behold, it is expedient in me that my servant John should write and keep a regular history, and assist you, my servant Joseph, in transcribing all things which shall be given you, until he is called to further duties."],["D&C",47,2,"Again, verily I say unto you that he can also lift up his voice in meetings, whenever it shall be expedient."],["D&C",47,3,"And again, I say unto you that it shall be appointed unto him to keep the church record and history continually; for Oliver Cowdery I have appointed to another office."],["D&C",47,4,"Wherefore, it shall be given him, inasmuch as he is faithful, by the Comforter, to write these things. Even so. Amen."],["D&C",48,1,"It is necessary that ye should remain for the present time in your places of abode, as it shall be suitable to your circumstances."],["D&C",48,2,"And inasmuch as ye have lands, ye shall impart to the eastern brethren;"],["D&C",48,3,"And inasmuch as ye have not lands, let them buy for the present time in those regions round about, as seemeth them good, for it must needs be necessary that they have places to live for the present time."],["D&C",48,4,"It must needs be necessary that ye save all the money that ye can, and that ye obtain all that ye can in righteousness, that in time ye may be enabled to purchase land for an inheritance, even the city."],["D&C",48,5,"The place is not yet to be revealed; but after your brethren come from the east there are to be certain men appointed, and to them it shall be given to know the place, or to them it shall be revealed."],["D&C",48,6,"And they shall be appointed to purchase the lands, and to make a commencement to lay the foundation of the city; and then shall ye begin to be gathered with your families, every man according to his family, according to his circumstances, and as is appointed to him by the presidency and the bishop of the church, according to the laws and commandments which ye have received, and which ye shall hereafter receive. Even so. Amen."],["D&C",49,1,"Hearken unto my word, my servants Sidney, and Parley, and Leman; for behold, verily I say unto you, that I give unto you a commandment that you shall go and preach my gospel which ye have received, even as ye have received it, unto the Shakers."],["D&C",49,2,"Behold, I say unto you, that they desire to know the truth in part, but not all, for they are not right before me and must needs repent."],["D&C",49,3,"Wherefore, I send you, my servants Sidney and Parley, to preach the gospel unto them."],["D&C",49,4,"And my servant Leman shall be ordained unto this work, that he may reason with them, not according to that which he has received of them, but according to that which shall be taught him by you my servants; and by so doing I will bless him, otherwise he shall not prosper."],["D&C",49,5,"Thus saith the Lord; for I am God, and have sent mine Only Begotten Son into the world for the redemption of the world, and have decreed that he that receiveth him shall be saved, and he that receiveth him not shall be damned—"],["D&C",49,6,"And they have done unto the Son of Man even as they listed; and he has taken his power on the right hand of his glory, and now reigneth in the heavens, and will reign till he descends on the earth to put all enemies under his feet, which time is nigh at hand—"],["D&C",49,7,"I, the Lord God, have spoken it; but the hour and the day no man knoweth, neither the angels in heaven, nor shall they know until he comes."],["D&C",49,8,"Wherefore, I will that all men shall repent, for all are under sin, except those which I have reserved unto myself, holy men that ye know not of."],["D&C",49,9,"Wherefore, I say unto you that I have sent unto you mine everlasting covenant, even that which was from the beginning."],["D&C",49,10,"And that which I have promised I have so fulfilled, and the nations of the earth shall bow to it; and, if not of themselves, they shall come down, for that which is now exalted of itself shall be laid low of power."],["D&C",49,11,"Wherefore, I give unto you a commandment that ye go among this people, and say unto them, like unto mine apostle of old, whose name was Peter:"],["D&C",49,12,"Believe on the name of the Lord Jesus, who was on the earth, and is to come, the beginning and the end;"],["D&C",49,13,"Repent and be baptized in the name of Jesus Christ, according to the holy commandment, for the remission of sins;"],["D&C",49,14,"And whoso doeth this shall receive the gift of the Holy Ghost, by the laying on of the hands of the elders of the church."],["D&C",49,15,"And again, verily I say unto you, that whoso forbiddeth to marry is not ordained of God, for marriage is ordained of God unto man."],["D&C",49,16,"Wherefore, it is lawful that he should have one wife, and they twain shall be one flesh, and all this that the earth might answer the end of its creation;"],["D&C",49,17,"And that it might be filled with the measure of man, according to his creation before the world was made."],["D&C",49,18,"And whoso forbiddeth to abstain from meats, that man should not eat the same, is not ordained of God;"],["D&C",49,19,"For, behold, the beasts of the field and the fowls of the air, and that which cometh of the earth, is ordained for the use of man for food and for raiment, and that he might have in abundance."],["D&C",49,20,"But it is not given that one man should possess that which is above another, wherefore the world lieth in sin."],["D&C",49,21,"And wo be unto man that sheddeth blood or that wasteth flesh and hath no need."],["D&C",49,22,"And again, verily I say unto you, that the Son of Man cometh not in the form of a woman, neither of a man traveling on the earth."],["D&C",49,23,"Wherefore, be not deceived, but continue in steadfastness, looking forth for the heavens to be shaken, and the earth to tremble and to reel to and fro as a drunken man, and for the valleys to be exalted, and for the mountains to be made low, and for the rough places to become smooth—and all this when the angel shall sound his trumpet."],["D&C",49,24,"But before the great day of the Lord shall come, Jacob shall flourish in the wilderness, and the Lamanites shall blossom as the rose."],["D&C",49,25,"Zion shall flourish upon the hills and rejoice upon the mountains, and shall be assembled together unto the place which I have appointed."],["D&C",49,26,"Behold, I say unto you, go forth as I have commanded you; repent of all your sins; ask and ye shall receive; knock and it shall be opened unto you."],["D&C",49,27,"Behold, I will go before you and be your rearward; and I will be in your midst, and you shall not be confounded."],["D&C",49,28,"Behold, I am Jesus Christ, and I come quickly. Even so. Amen."],["D&C",50,1,"Hearken, O ye elders of my church, and give ear to the voice of the living God; and attend to the words of wisdom which shall be given unto you, according as ye have asked and are agreed as touching the church, and the spirits which have gone abroad in the earth."],["D&C",50,2,"Behold, verily I say unto you, that there are many spirits which are false spirits, which have gone forth in the earth, deceiving the world."],["D&C",50,3,"And also Satan hath sought to deceive you, that he might overthrow you."],["D&C",50,4,"Behold, I, the Lord, have looked upon you, and have seen abominations in the church that profess my name."],["D&C",50,5,"But blessed are they who are faithful and endure, whether in life or in death, for they shall inherit eternal life."],["D&C",50,6,"But wo unto them that are deceivers and hypocrites, for, thus saith the Lord, I will bring them to judgment."],["D&C",50,7,"Behold, verily I say unto you, there are hypocrites among you, who have deceived some, which has given the adversary power; but behold such shall be reclaimed;"],["D&C",50,8,"But the hypocrites shall be detected and shall be cut off, either in life or in death, even as I will; and wo unto them who are cut off from my church, for the same are overcome of the world."],["D&C",50,9,"Wherefore, let every man beware lest he do that which is not in truth and righteousness before me."],["D&C",50,10,"And now come, saith the Lord, by the Spirit, unto the elders of his church, and let us reason together, that ye may understand;"],["D&C",50,11,"Let us reason even as a man reasoneth one with another face to face."],["D&C",50,12,"Now, when a man reasoneth he is understood of man, because he reasoneth as a man; even so will I, the Lord, reason with you that you may understand."],["D&C",50,13,"Wherefore, I the Lord ask you this question—unto what were ye ordained?"],["D&C",50,14,"To preach my gospel by the Spirit, even the Comforter which was sent forth to teach the truth."],["D&C",50,15,"And then received ye spirits which ye could not understand, and received them to be of God; and in this are ye justified?"],["D&C",50,16,"Behold ye shall answer this question yourselves; nevertheless, I will be merciful unto you; he that is weak among you hereafter shall be made strong."],["D&C",50,17,"Verily I say unto you, he that is ordained of me and sent forth to preach the word of truth by the Comforter, in the Spirit of truth, doth he preach it by the Spirit of truth or some other way?"],["D&C",50,18,"And if it be by some other way it is not of God."],["D&C",50,19,"And again, he that receiveth the word of truth, doth he receive it by the Spirit of truth or some other way?"],["D&C",50,20,"If it be some other way it is not of God."],["D&C",50,21,"Therefore, why is it that ye cannot understand and know, that he that receiveth the word by the Spirit of truth receiveth it as it is preached by the Spirit of truth?"],["D&C",50,22,"Wherefore, he that preacheth and he that receiveth, understand one another, and both are edified and rejoice together."],["D&C",50,23,"And that which doth not edify is not of God, and is darkness."],["D&C",50,24,"That which is of God is light; and he that receiveth light, and continueth in God, receiveth more light; and that light groweth brighter and brighter until the perfect day."],["D&C",50,25,"And again, verily I say unto you, and I say it that you may know the truth, that you may chase darkness from among you;"],["D&C",50,26,"He that is ordained of God and sent forth, the same is appointed to be the greatest, notwithstanding he is the least and the servant of all."],["D&C",50,27,"Wherefore, he is possessor of all things; for all things are subject unto him, both in heaven and on the earth, the life and the light, the Spirit and the power, sent forth by the will of the Father through Jesus Christ, his Son."],["D&C",50,28,"But no man is possessor of all things except he be purified and cleansed from all sin."],["D&C",50,29,"And if ye are purified and cleansed from all sin, ye shall ask whatsoever you will in the name of Jesus and it shall be done."],["D&C",50,30,"But know this, it shall be given you what you shall ask; and as ye are appointed to the head, the spirits shall be subject unto you."],["D&C",50,31,"Wherefore, it shall come to pass, that if you behold a spirit manifested that you cannot understand, and you receive not that spirit, ye shall ask of the Father in the name of Jesus; and if he give not unto you that spirit, then you may know that it is not of God."],["D&C",50,32,"And it shall be given unto you, power over that spirit; and you shall proclaim against that spirit with a loud voice that it is not of God—"],["D&C",50,33,"Not with railing accusation, that ye be not overcome, neither with boasting nor rejoicing, lest you be seized therewith."],["D&C",50,34,"He that receiveth of God, let him account it of God; and let him rejoice that he is accounted of God worthy to receive."],["D&C",50,35,"And by giving heed and doing these things which ye have received, and which ye shall hereafter receive—and the kingdom is given you of the Father, and power to overcome all things which are not ordained of him—"],["D&C",50,36,"And behold, verily I say unto you, blessed are you who are now hearing these words of mine from the mouth of my servant, for your sins are forgiven you."],["D&C",50,37,"Let my servant Joseph Wakefield, in whom I am well pleased, and my servant Parley P. Pratt go forth among the churches and strengthen them by the word of exhortation;"],["D&C",50,38,"And also my servant John Corrill, or as many of my servants as are ordained unto this office, and let them labor in the vineyard; and let no man hinder them doing that which I have appointed unto them—"],["D&C",50,39,"Wherefore, in this thing my servant Edward Partridge is not justified; nevertheless let him repent and he shall be forgiven."],["D&C",50,40,"Behold, ye are little children and ye cannot bear all things now; ye must grow in grace and in the knowledge of the truth."],["D&C",50,41,"Fear not, little children, for you are mine, and I have overcome the world, and you are of them that my Father hath given me;"],["D&C",50,42,"And none of them that my Father hath given me shall be lost."],["D&C",50,43,"And the Father and I are one. I am in the Father and the Father in me; and inasmuch as ye have received me, ye are in me and I in you."],["D&C",50,44,"Wherefore, I am in your midst, and I am the good shepherd, and the stone of Israel. He that buildeth upon this rock shall never fall."],["D&C",50,45,"And the day cometh that you shall hear my voice and see me, and know that I am."],["D&C",50,46,"Watch, therefore, that ye may be ready. Even so. Amen."]]);
